indexer.query:
query Readiness($router:String!,$registry:String!){
 SyncStatus(where:{chainId:{_eq:10143},router:{_eq:$router},registry:{_eq:$registry}}){chainId router registry blockNumber}
 Agent(where:{chainId:{_eq:10143},registry:{_eq:$registry}},order_by:{agentId:asc}){agentId owner tasksCompleted shardsCreated}
 TaskExecution_aggregate(where:{chainId:{_eq:10143},router:{_eq:$router}}){aggregate{count}}
 TaskExecution(where:{chainId:{_eq:10143},router:{_eq:$router}},limit:1000,order_by:[{blockNumber:asc},{logIndex:asc}]){agentId taskId inputHash outputHash proofHash leaf blockNumber blockHash transactionHash logIndex shard{address sequenceNonce executor creationTx}}
 MerkleBatch(where:{chainId:{_eq:10143},router:{_eq:$router}},limit:1000,order_by:{blockNumber:asc}){batchId blockNumber blockHash root leafCount status committedRoot committedLeafCount commitmentTx commitmentBlock}
 BatchCommitment(where:{chainId:{_eq:10143},router:{_eq:$router}},limit:1000,order_by:{fromBlock:asc}){batchId root leafCount fromBlock toBlock verified transactionHash}
 }
